function esc(s) {
  return s.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

const tierTags = {
  major: { interests: ["media-entertainment", "communication", "creating-designing"], skills: ["storytelling", "communication", "writing"], workStyles: ["creative", "collaborative", "people-focused"] },
  specialized: { interests: ["media-entertainment", "communication"], skills: ["writing", "storytelling", "creativity"], workStyles: ["creative", "collaborative", "independent"] },
  emerging: { interests: ["media-entertainment", "technology", "entrepreneurship"], skills: ["storytelling", "creativity", "communication"], workStyles: ["creative", "collaborative", "technical"] },
  interdisciplinary: { interests: ["media-entertainment", "business-strategy", "communication"], skills: ["storytelling", "persuasion", "communication"], workStyles: ["collaborative", "creative", "people-focused"] },
  hidden: { interests: ["media-entertainment", "communication"], skills: ["organization", "writing", "storytelling"], workStyles: ["independent", "hands-on", "creative"] },
};

let out = `import { GrowthOutlook } from "../../../src/generated/prisma/client";

import { c } from "../career-builder";

/** Media & Entertainment category — batch 9 of the 1,000+ career catalog. */
export const MEDIA_ENTERTAINMENT_CAREERS = [
`;

for (const row of careers) {
  const [slug, title, tagline, summary, min, max, opts = {}] = row;
  const tags = tierTags[opts.tier ?? "specialized"];
  const lines = [`  c({`];
  lines.push(`    slug: "${slug}",`);
  lines.push(`    title: "${esc(title)}",`);
  lines.push(`    tagline: "${esc(tagline)}",`);
  lines.push(`    summary: "${esc(summary)}",`);
  lines.push(`    salaryMin: ${min},`);
  lines.push(`    salaryMax: ${max},`);
  if (opts.anchor) lines.push(`    anchor: true,`);
  if (opts.featured) lines.push(`    featured: true,`);
  if (opts.tier) lines.push(`    tier: "${opts.tier}",`);
  if (opts.growth) lines.push(`    growthOutlook: GrowthOutlook.${opts.growth},`);
  if (opts.companies) lines.push(`    exampleCompanies: [${opts.companies.map((x) => `"${x}"`).join(", ")}],`);
  if (opts.aliases) lines.push(`    aliases: [${opts.aliases.map((x) => `"${esc(x)}"`).join(", ")}],`);
  if (opts.related) lines.push(`    related: [${opts.related.map((x) => `"${x}"`).join(", ")}],`);
  lines.push(`    interests: [${tags.interests.map((x) => `"${x}"`).join(", ")}],`);
  lines.push(`    skills: [${tags.skills.map((x) => `"${x}"`).join(", ")}],`);
  lines.push(`    workStyles: [${tags.workStyles.map((x) => `"${x}"`).join(", ")}],`);
  lines.push(`    commonTasks: "${esc(opts.tasks ?? "")}",`);
  lines.push(`    downsides: "${esc(opts.downsides ?? "")}",`);
  lines.push(`  }),`);
  out += lines.join("\n") + "\n";
}

out += `];\n`;

const outPath = path.join(__dirname, "../data/categories/media-entertainment.ts");
fs.mkdirSync(path.dirname(outPath), { recursive: true });
fs.writeFileSync(outPath, out);
console.log(`Generated ${careers.length} media-entertainment careers → ${outPath}`);
